r"""infra_from_roster.py — ENUM-01 (c) (DAY ORDER 6, 2026-10-25): the infrastructure lines of every market are generated from the roster of record, never typed.
For each live roster node (list_nodes / nodes.json; ROSTER_FILE=<copy> for a dry run) it writes:
  · ark bucket line      allooloo-ark-<cc>-cm-kg in the node's ark region (policy line: ARK / EU_ARK / ROW_ARK of RAILS\job\provision_jobs.py, read from its source)
  · IAM policy lines     the ark-writer put + list statements for that bucket and prefix <node>/ (the shape of AWS\ark-writer-policy.json)
  · Origin CA hostnames  the certificate a door needs: own zone <cc>-cm-kg.ai + *.<cc>-cm-kg.ai, or the shared eu-cm-kg.ai + *.eu-cm-kg.ai for a door under it
  · standby service      ECS allooloo-standby-<cc> in the ark region (desired 0), image allooloo-standby/cmkg-door (the shape of zones-032\standby_deploy.py)
and the CloudShell block for any node whose bucket is not there yet (bucket + Object Lock GOVERNANCE 365 + public access block + put-only policy), so the
next node's block is generated, not typed. With --check it confirms each bucket exists (HeadBucket, read-only, as standby-deployer — the key is read
in-process and never printed). A roster node with no ark-region policy line stops the rail and is named.
Usage: python -X utf8 -I infra_from_roster.py [--check] [--out <dir>]"""
import os, sys, json, re, datetime
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE); import roster
PJ = os.path.join(HERE, '..', 'job', 'provision_jobs.py')
def policy_maps():
    """the ark-region policy of record, read from provision_jobs.py's own source (the constant block before the tenant guard), not copied here"""
    src = open(PJ, encoding='utf-8').read(); seg = src[src.index("NODES = {'nl'"):src.index('# ENUM-01 (DAY ORDER 6, 2026-10-25): region / ark')]
    ns = {}; exec(seg, ns); return ns['ARK']
ARK = policy_maps()
nodes = roster.load(); codes = [roster.cc_of(n) for n in nodes]
roster.require('ark region (provision_jobs ARK)', ARK, codes)
day = datetime.date.today().isoformat()
out_dir = sys.argv[sys.argv.index('--out') + 1] if '--out' in sys.argv else os.path.join(HERE, f'infra-{day}')
os.makedirs(out_dir, exist_ok=True)
lines = []
for n in nodes:
    cc = roster.cc_of(n); node = n['node']; door = str(n.get('door') or '').rstrip('/'); host = door.split('://')[-1]
    zone = 'eu-cm-kg.ai' if host.endswith('.eu-cm-kg.ai') else f'{node}.ai'
    lines.append({'node': node, 'country': n.get('country'), 'door': door,
                  'ark': {'bucket': f'allooloo-ark-{node}', 'region': ARK[cc], 'prefix': f'{node}/'},
                  'iam': {'put': f'arn:aws:s3:::allooloo-ark-{node}/{node}/*', 'list': f'arn:aws:s3:::allooloo-ark-{node}'},
                  'origin_ca': {'zone': zone, 'hostnames': [zone, f'*.{zone}']},
                  'standby': {'cluster': 'allooloo-standby', 'service': f'allooloo-standby-{cc}', 'region': ARK[cc], 'desired': 0, 'image': 'allooloo-standby/cmkg-door', 'secret': f'allooloo-standby/{cc}-origin-ca'}})
present = {}
if '--check' in sys.argv:
    import boto3, botocore
    k = open(r'C:\MATTHEWKEDDY\AGENT KEYS\aws-standby-deployer.txt', encoding='utf-8').read().split()
    for l in lines:
        s3 = boto3.client('s3', region_name=l['ark']['region'], aws_access_key_id=k[0], aws_secret_access_key=k[1])
        try: s3.head_bucket(Bucket=l['ark']['bucket']); present[l['node']] = 'present'
        except botocore.exceptions.ClientError as e: present[l['node']] = 'absent' if e.response['Error']['Code'] in ('404', 'NoSuchBucket') else f"present (HeadBucket {e.response['Error']['Code']}: exists, not readable by this key)"
        except Exception as e: present[l['node']] = f'not read ({type(e).__name__})'
for l in lines: l['ark']['state'] = present.get(l['node'], 'not checked')
missing = [l for l in lines if l['ark']['state'] == 'absent']
block = ['# CloudShell block generated by infra_from_roster.py (ENUM-01) from the roster of record — ' + day, '# one loop per missing ark bucket; the CEO runs it (a bucket is the CEO\'s hand)']
for l in missing:
    b, r, node = l['ark']['bucket'], l['ark']['region'], l['node']
    block += [f'aws s3api create-bucket --bucket {b} --region {r}' + ('' if r == 'us-east-1' else f' --create-bucket-configuration LocationConstraint={r}') + ' --object-lock-enabled-for-bucket',
              f"aws s3api put-object-lock-configuration --bucket {b} --region {r} --object-lock-configuration '{{\"ObjectLockEnabled\":\"Enabled\",\"Rule\":{{\"DefaultRetention\":{{\"Mode\":\"GOVERNANCE\",\"Days\":365}}}}}}'",
              f'aws s3api put-public-access-block --bucket {b} --region {r} --public-access-block-configuration BlockPublicAcls=true,IgnorePublicAcls=true,BlockPublicPolicy=true,RestrictPublicBuckets=true',
              f"aws iam put-user-policy --user-name ark-writer --policy-name ark-writer-put-{l['node'].split('-')[0]} --policy-document '{json.dumps({'Version': '2012-10-17', 'Statement': [{'Effect': 'Allow', 'Action': ['s3:PutObject', 's3:PutObjectRetention'], 'Resource': [l['iam']['put']]}, {'Effect': 'Allow', 'Action': ['s3:ListBucket'], 'Resource': [l['iam']['list']], 'Condition': {'StringLike': {'s3:prefix': [node + '/*']}}}]})}'"]
if not missing: block.append('# nothing to run: every roster node has its ark bucket' if present else '# not checked (run with --check)')
json.dump({'generated': day, 'roster': os.environ.get('ROSTER_FILE') or 'list_nodes', 'nodes': lines}, open(os.path.join(out_dir, 'infra.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
open(os.path.join(out_dir, 'cloudshell-missing.sh'), 'w', encoding='utf-8', newline='\n').write('\n'.join(block) + '\n')
print(f'infra lines for {len(lines)} roster nodes -> {out_dir}')
if present: print('ark buckets:', sum(1 for v in present.values() if v.startswith('present')), 'present ·', len(missing), 'absent', ('· ' + ', '.join(l['node'] for l in missing)) if missing else '')
